#!/usr/bin/env python3
"""
Round 115b (tiles), 29 September 2026.

scripts/medical_culprits.py (new: the medical industry's culprits from
Wikipedia and Wikidata), scripts/lib/wdtools.py (as in 114b), and
scripts/capture_stb.py asked country by country (its one query timed out).

Whole files, each written only if it differs.
"""
import base64, pathlib

FILES = {'scripts/medical_culprits.py': '', 'scripts/lib/wdtools.py': '', 'scripts/capture_stb.py': ''}
DELETE = []


def main():
    for p, b in FILES.items():
        data = base64.b64decode(b)
        f = pathlib.Path(p)
        if f.exists() and f.read_bytes() == data:
            print(f"round115b: {p} already up to date")
            continue
        f.parent.mkdir(parents=True, exist_ok=True)
        f.write_bytes(data)
        print(f"round115b: wrote {p}")
    for p in DELETE:
        f = pathlib.Path(p)
        if f.exists():
            f.unlink()
            print(f"round115b: deleted {p}")


if __name__ == "__main__":
    main()
